#include <iostream>
using namespace std;

void compteEnrere(int n) {
    if (n > 0) {
        cout << n << endl;
        compteEnrere(n - 1);  // Pas recursiu
    }
    // Cas base: quan n <= 0, no fa res
}

int main() {
    int n;
    cin >> n;
    compteEnrere(n);
    return 0;
}

