#include <iostream>
#include <vector>
using namespace std;

int cercaBinaria(const vector<int>& v, int x) {
    int esq = 0, dre = v.size() - 1;
    while (esq <= dre) {
        int mig = (esq + dre) / 2;
        if (v[mig] == x) return mig;
        else if (v[mig] < x) esq = mig + 1;
        else dre = mig - 1;
    }
    return -1;  // No trobat
}

int main() {
    int n, x;
    cin >> n;
    vector<int> v(n);
    for (int i = 0; i < n; ++i) cin >> v[i];
    cin >> x;

    cout << cercaBinaria(v, x) << endl;
    return 0;
}

#include <iostream>
using namespace std;

double potencia(double x, int n) {
    if (n == 0) return 1;  // Cas base
    if (n % 2 == 0) {
        double mig = potencia(x, n / 2);
        return mig * mig;  // Pas recursiu (parell)
    }
    return x * potencia(x, n - 1);  // Pas recursiu (imparell)
}

int main() {
    double x;
    int n;
    cin >> x >> n;
    cout << potencia(x, n) << endl;
    return 0;
}
